    def config5gdeployment(self, nettype, until_timeout=None):
        """
        execute Config5GDeployment command to configure the UE 5G deployment
        Mate 30, Mate 30 PRO supported only

        :param int nettype: 0:"Auto selection", 8:"5G NSA", 20:"5G SA + 5G NSA"
        :param Optional[int] until_timeout: execution timeout in second, 10s by default

        :return: CommandResult
        e.g. CommandResult.dictionary
        {
            "CMD": "Config5GDeployment",
            "EQIndex": 1, # 1 means the first UE,
                          # 2 means the second UE, and so forth.
            "Param": {
                 "State": 0  # return 0 if success, otherwise return the error codes
            }
        }
        """
        return self._api.Config5GDeployment(self._info.eqindex, nettype, until_timeout=until_timeout)

    def getparammac(self, until_timeout=None):
        """
        execute GetParamMAC command to get mac layer downlink/uplink throughput.

        :param Optional[int] until_timeout: execution timeout in second, 10s by default

        :return: CommandResult
        e.g. CommandResult.dictionary
        {
            "CMD": "GetParamMAC",
            "EQIndex": 1, 1 # {1~n}, 1 means the first UE, 2 means the second UE, and so forth.
            "Param": {
                     "State": 0, # return 0 if success, otherwise return the error codes
                     "MACDL": 2000000, # bps, downlink throughput, if State is 0.
                     "MACUL": 1000000 # bps, uplink throughput, if State is 0.
            }
        }
        """
        return self._api.GetParamMAC(self._info.eqindex, until_timeout=until_timeout)

    def getparamimsi(self, until_timeout=None):
        """
        execute GetParamIMSI command to get the IMSI on a specific UE

        :param Optional[int] until_timeout: execution timeout in second, 10s by default

        :return: CommandResult
        e.g. CommandResult.dictionary
        {
            "CMD": "GetParamIMSI",
            "EQIndex": 1, 1 # {1~n}, 1 means the first UE, 2 means the second UE, and so forth.
            "Param": {
                        "State": 0,  # return 0 if success, otherwise return the error codes
                        "IMSI": "460020315993651"  # UE’s IMSI if state is 0.
            }
        }
        """
        return self._api.GetParamIMSI(self._info.eqindex, until_timeout=until_timeout)

    def getpduinfo(self, apn, until_timeout=None):
        """
        execute GetPDUInfo command to get the PDU ip address

        :param str apn: apn address
        :param Optional[int] until_timeout: execution timeout in second, 10s by default

        :return: CommandResult
        e.g. CommandResult.dictionary
        {
            "CMD": "GetPDUInfo",
            "EQIndex": 1,  # {1~n}, 1 means the first UE, 2 means the second UE, and so forth.
            "Param": {
                   "State": 0,  # return 0 if success, otherwise return the error codes
                   "APN": "wap1nokiacom", # PDU APN address
                   "IP": "1.1.1.1"  # UE’s IP state is 0
            }
        }

        """
        return self._api.GetPDUInfo(self._info.eqindex, apn, until_timeout=until_timeout)

    def exportmessagedetail(self, exportfilename, logfile, until_timeout=None):
        """
        execute ExportMessageDetail command to export L3 Messages to XML file after StopLog command

        :param str exportfilename: output target xml file path, if "", the file will be exported to default folder
        `Data\\Export`
        :param str logfile: input .source formatted raw L3 message log file path
        :param Optional[int] until_timeout: execution timeout in second, 10s by default

        :return: CommandResult
        e.g. CommandResult.dictionary
        {
            "CMD": "ExportMessageDetail",
            "Param": {
                     "State": 0  # return 0 if success, otherwise return the error codes
            }
        }
        """
        return self._api.ExportMessageDetail(exportfilename, logfile, until_timeout=until_timeout)

    def exportlogfile(self, templatename, exportfilename, logfile, until_timeout=None):
        """
        execute ExportLogfile command to export the raw measurement and Event logs to csv formatted file after
        StopLog command

        :param str templatename: filter template file path for exmporting
        :param str exportfilename: output target csv file path, if "", the file will be exported to default folder
        `Data\\Export`
        :param str logfile: input .src formatted raw measurement and event log file path
        :param Optional[int] until_timeout: execution timeout in second, 10s by default

        :return: CommandResult
        e.g. CommandResult.dictionary
        {
            "CMD": "ExportLogfile",
            "Param": {
                     "State": 0  # return 0 if success, otherwise return the error codes
            }
        }
        """
        return self._api.ExportLogfile(templatename,
                                       exportfilename,
                                       logfile,
                                       until_timeout=until_timeout)

