    def sendat(self, command, timeout, succstr=None, until_timeout=None):
        """
        execute SendATCommand command to send AT command to specific UE

        :param str command: AT command
        :param int timeout: AT command timeout in milliseconds
        :param Optional[str] succstr: customized success flag returned from device when succeeded executing at command
        :param Optional[int] until_timeout: execution timeout in second, 10s by default

        :return: CommandResult
        e.g. CommandResult.dictionary
        {
            "CMD": "SendATCommand",
            "EQIndex": 1,  # {1~n}, 1 means the first UE, 2 means the second UE, and so forth.
            "Param": {
                   "State": 0  # return 0 if success, otherwise return the error codes
                   "Command": "AT",  # corresponding AT command name in Req
                   "Back": "OK"  # AT command execution result.

            }
        }
        """
        return self._api.SendAT(self._info.eqindex, command, timeout, succstr=succstr, until_timeout=until_timeout)

    def setups_nssai(self, id, type, apn, ssc_mode, s_nssai, until_timeout=None):
        """
        setups nssai

        :param Optional[int] until_timeout: execution timeout in second, 10s by default
        """
        until_timeout = int(until_timeout) if until_timeout else None
        id = int(id)
        ssc_mode = int(ssc_mode) if ssc_mode else None
        return self._api.SetupS_NSSAI(self._info.eqindex, id, type, apn, ssc_mode, s_nssai, until_timeout=until_timeout)

